const upsertAccountFeedbackVote = `-- name: UpsertAccountFeedbackVote :execrows
INSERT INTO feedback_votes (workspace_id, item_id, user_id, contributor_id, direction)
SELECT item.workspace_id,
       item.id,
       contributor.user_id,
       contributor.id,
       $1
FROM feedback_items item
INNER JOIN feedback_boards fb ON fb.id = item.board_id AND fb.workspace_id = item.workspace_id
INNER JOIN workspace_members wm
    ON wm.workspace_id = item.workspace_id
   AND wm.user_id = $2
   AND wm.role IN ('admin', 'member')
INNER JOIN team_members tm ON tm.team_id = fb.team_id AND tm.user_id = wm.user_id
INNER JOIN users current_actor ON current_actor.user_id = wm.user_id AND current_actor.is_active = true AND current_actor.is_system = false
INNER JOIN feedback_contributors contributor
    ON contributor.portal_id = item.portal_id
   AND contributor.user_id = wm.user_id
   AND contributor.kind = 'account'
WHERE item.workspace_id = $3
  AND item.id = $4
  AND item.deleted_at IS NULL
  AND item.merged_into_item_id IS NULL
  AND (CAST($5 AS boolean) OR fb.team_id = ANY(CAST($6 AS uuid[])))
ON CONFLICT (item_id, contributor_id)
DO UPDATE SET direction = EXCLUDED.direction
`

type UpsertAccountFeedbackVoteParams struct {
	Direction         int16
	ActorID           uuid.UUID
	WorkspaceID       uuid.UUID
	ItemID            uuid.UUID
	AllTeams          bool
	CredentialTeamIds []uuid.UUID
}

func (q *Queries) UpsertAccountFeedbackVote(ctx context.Context, arg UpsertAccountFeedbackVoteParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertAccountFeedbackVote,
		arg.Direction,
		arg.ActorID,
		arg.WorkspaceID,
		arg.ItemID,
		arg.AllTeams,
		arg.CredentialTeamIds,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertContributorFeedbackVote = `-- name: UpsertContributorFeedbackVote :execrows
INSERT INTO feedback_votes (workspace_id, item_id, user_id, contributor_id, direction)
SELECT item.workspace_id,
       item.id,
       contributor.user_id,
       contributor.id,
       $1
FROM feedback_items item
INNER JOIN feedback_portals portal ON portal.id = item.portal_id AND portal.is_public = true
INNER JOIN feedback_contributors contributor
    ON contributor.portal_id = item.portal_id
   AND contributor.id = $2
WHERE item.workspace_id = $3
  AND item.id = $4
  AND item.deleted_at IS NULL
  AND item.merged_into_item_id IS NULL
  AND contributor.blocked_at IS NULL
  AND contributor.kind <> 'anonymous'
ON CONFLICT (item_id, contributor_id)
DO UPDATE SET direction = EXCLUDED.direction
`

type UpsertContributorFeedbackVoteParams struct {
	Direction     int16
	ContributorID uuid.UUID
	WorkspaceID   uuid.UUID
	ItemID        uuid.UUID
}

func (q *Queries) UpsertContributorFeedbackVote(ctx context.Context, arg UpsertContributorFeedbackVoteParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertContributorFeedbackVote,
		arg.Direction,
		arg.ContributorID,
		arg.WorkspaceID,
		arg.ItemID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
